def total(scores):
    """返回分数列表的总和。"""
    sum_value = 0
    for s in scores:
        sum_value += s
    return sum_value

def average(scores):
    """返回平均分，空列表返回 0。"""
    if len(scores) == 0:
        return 0
    return total(scores) / len(scores)

