import functools

def repeat(times):
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            result = None
            for _ in range(times):
                result = func(*args, **kwargs)
            return result
        return wrapper
    return decorator

@repeat(3)
def greet(name):
    print('你好，' + name)
    return name

greet('林晓')
print('保留名称', greet.__name__)
print('保留文档', greet.__doc__)

